<?php
/** Apply PDF protection, backup, restore-preview, production-restore, dry-run, and live database restore migrations. */
if (PHP_SAPI !== 'cli') { fwrite(STDERR, "CLI only.\n"); exit(1); }
require_once __DIR__ . '/../includes/env_loader.php';
$dbHost=env('DB_HOST','localhost');$dbName=env('DB_NAME','iscan_db');$dbUser=env('DB_USER','root');$dbPass=env('DB_PASS','');
$migrations=['040_pdf_fingerprint_registry.sql','041_pdf_protection_jobs.sql','042_pdf_fingerprint_triggers.sql','043_pdf_fingerprint_trigger_release_fix.sql','044_pdf_fingerprint_owner_index_fix.sql','045_database_backup_jobs.sql','046_database_restore_preview_jobs.sql','047_production_restore_control_jobs.sql','048_pdf_protection_dry_run_flag.sql','049_database_live_restore_jobs.sql'];
try{$pdo=new PDO("mysql:host={$dbHost};dbname={$dbName};charset=utf8mb4",$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo->exec('CREATE TABLE IF NOT EXISTS migrations (id INT AUTO_INCREMENT PRIMARY KEY,migration_name VARCHAR(255) NOT NULL UNIQUE,executed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');$done=array_flip($pdo->query('SELECT migration_name FROM migrations')->fetchAll(PDO::FETCH_COLUMN));foreach($migrations as $migration){if(isset($done[$migration])){echo "SKIP {$migration}\n";continue;}$path=__DIR__.'/migrations/'.$migration;if(!is_file($path))throw new RuntimeException("Migration file not found: {$migration}");$pdo->exec(file_get_contents($path));$stmt=$pdo->prepare('INSERT INTO migrations (migration_name) VALUES (?)');$stmt->execute([$migration]);echo "OK   {$migration}\n";}}catch(Throwable $e){fwrite(STDERR,'ERROR: '.$e->getMessage()."\n");exit(1);}
